(() => {
 const feedback = document.getElementById('puzzle-feedback');
 if (typeof Chess === 'undefined') {
   feedback.textContent = 'The chess rules library did not load. Check your internet connection and refresh.';
   return;
 }

 // Each answer is stored as an exact from/to move and the SAN generated by chess.js.
 // The validation below prevents a broken FEN or mismatched answer from being shown.
 const puzzleData = [
   {
     title: 'Back-rank mate', level: 'Beginner', theme: 'Checkmate',
     fen: '6k1/5ppp/8/8/8/8/5PPP/3R2K1 w - - 0 1',
     solution: { from: 'd1', to: 'd8', san: 'Rd8#' },
     hint: ['The d-file is open all the way to the eighth rank.', 'Move the rook to d8. The black king is boxed in by its own pawns.'],
     why: 'Rd8# is checkmate. The rook checks along the eighth rank, and Black’s own pawns block the king’s escape squares.'
   },
   {
     title: 'Knight fork', level: 'Beginner', theme: 'Fork',
     fen: '6k1/7q/8/8/4N3/8/8/K7 w - - 0 1',
     solution: { from: 'e4', to: 'f6', san: 'Nf6+' },
     hint: ['Look for a knight move that gives check.', 'A knight on f6 checks the king and attacks the queen on h7 at the same time.'],
     why: 'Nf6+ is a fork: the knight checks the king on g8 while attacking the queen on h7. Black must answer the check, allowing White to win the queen.'
   },
   {
     title: 'Queen-supported mate', level: 'Beginner', theme: 'Checkmate',
     fen: '7k/6pp/5KQ1/8/8/8/8/8 w - - 0 1',
     solution: { from: 'g6', to: 'g7', san: 'Qxg7#' },
     hint: ['The queen can capture the pawn beside the black king.', 'The white king protects the queen after it captures on g7.'],
     why: 'Qxg7# is checkmate. The white king protects the queen on g7, and the queen controls the black king’s remaining escape squares.'
   },
   {
     title: 'Mirror-image queen mate', level: 'Beginner', theme: 'Checkmate',
     fen: 'k7/pp6/1QK5/8/8/8/8/8 w - - 0 1',
     solution: { from: 'b6', to: 'b7', san: 'Qxb7#' },
     hint: ['The queen can capture the pawn next to the black king.', 'The white king protects the queen on b7.'],
     why: 'Qxb7# is checkmate. The king supports the queen, while the queen covers the black king’s escape squares.'
   }
 ];

 function validatePuzzle(p) {
   try {
     const test = new Chess(p.fen);
     const move = test.moves({ square: p.solution.from, verbose: true })
       .find(candidate => candidate.to === p.solution.to);
     return Boolean(move && move.san === p.solution.san);
   } catch (error) {
     return false;
   }
 }

 const puzzles = puzzleData.filter(p => {
   const valid = validatePuzzle(p);
   if (!valid) console.error('Chesscraft skipped an invalid puzzle:', p.title);
   return valid;
 });

 let index = 0;
 let game = null;
 let selected = null;
 let solved = false;
 let attempts = 0;
 let correct = 0;
 let hintStep = 0;
 let moveNo = 0;
 const $ = id => document.getElementById(id);

 function filtered() {
   const difficulty = $('puzzle-difficulty').value;
   const theme = $('puzzle-theme').value;
   return puzzles.map((p, i) => ({ ...p, index: i })).filter(p =>
     (difficulty === 'all' || p.level === difficulty) &&
     (theme === 'all' || p.theme === theme)
   );
 }

 function current() {
   const available = filtered();
   if (!available.length) return null;
   return available.find(p => p.index === index) || available[0];
 }

 function load() {
   const p = current();
   if (!p) {
     $('puzzle-title').textContent = 'No matching puzzles';
     $('puzzle-feedback').className = 'puzzle-feedback';
     $('puzzle-feedback').textContent = puzzles.length
       ? 'Try changing the difficulty or theme filters.'
       : 'No puzzles passed the position and answer checks. Refresh the page or check the chess rules library.';
     // Keep the last rendered board in place if a future filter has no matches.
     // This avoids an apparently broken/blank board when content is unavailable.
     return;
   }

   index = p.index;
   game = new Chess(p.fen);
   selected = null;
   solved = false;
   attempts = 0;
   correct = 0;
   hintStep = 0;
   moveNo = 0;
   $('puzzle-title').textContent = p.title;
   $('puzzle-level').textContent = p.level.toUpperCase();
   $('puzzle-task').textContent = p.theme === 'Checkmate' ? 'Find checkmate.' : 'Find the tactical move.';
   $('puzzle-description').textContent = `${game.turn() === 'w' ? 'White' : 'Black'} to move. ${p.theme === 'Fork' ? 'Find a double attack.' : 'Look for the forcing move.'}`;
   $('puzzle-theme-label').textContent = p.theme.toUpperCase();
   $('puzzle-rating').textContent = p.level;
   $('puzzle-feedback').className = 'puzzle-feedback';
   $('puzzle-feedback').textContent = 'Select a piece, then select its destination square.';
   $('hint-box').hidden = true;
   $('hint-box').textContent = '';
   $('puzzle-attempts').textContent = '0';
   $('puzzle-accuracy').textContent = '—';
   $('puzzle-completed').textContent = ChessProgress.get().puzzlesSolved;
   $('move-counter').textContent = 'Move 0';
   $('turn-indicator').textContent = game.turn() === 'w' ? 'White to move' : 'Black to move';
   render();
 }

 function render(legalMoves = []) {
   const board = game.board();
   const files = 'abcdefgh';
   let html = '';
   for (let row = 0; row < 8; row++) {
     for (let col = 0; col < 8; col++) {
       const square = files[col] + (8 - row);
       const piece = board[row][col];
       const light = (row + col) % 2 === 0;
       let classes = 'square ' + (light ? 'light' : 'dark');
       if (selected === square) classes += ' selected';
       if (legalMoves.some(move => move.to === square)) classes += piece ? ' capture' : ' legal';
       html += `<button type="button" class="${classes}" data-square="${square}" role="gridcell" aria-label="${square}${piece ? ' ' + (piece.color === 'w' ? 'white' : 'black') + ' ' + pieceName(piece.type) : ''}">${piece ? pieceSymbol(piece) : ''}</button>`;
     }
   }
   $('puzzle-board').innerHTML = html;
   $('puzzle-board').querySelectorAll('[data-square]').forEach(button => {
     button.addEventListener('click', () => clickSquare(button.dataset.square));
   });
 }

 function pieceName(type) {
   return ({ k: 'king', q: 'queen', r: 'rook', b: 'bishop', n: 'knight', p: 'pawn' })[type];
 }

 function pieceSymbol(piece) {
   const white = { k: '♔', q: '♕', r: '♖', b: '♗', n: '♘', p: '♙' };
   const black = { k: '♚', q: '♛', r: '♜', b: '♝', n: '♞', p: '♟' };
   return `<span class="${piece.color === 'w' ? 'piece-white' : 'piece-black'}">${(piece.color === 'w' ? white : black)[piece.type]}</span>`;
 }

 function clickSquare(square) {
   if (solved) return;
   const piece = game.get(square);
   if (selected) {
     const legalMoves = game.moves({ square: selected, verbose: true });
     const chosen = legalMoves.find(move => move.to === square);
     if (chosen) {
       play(selected, square);
       return;
     }
     if (piece && piece.color === game.turn()) {
       selected = square;
       render(game.moves({ square, verbose: true }));
       return;
     }
     selected = null;
     render();
     return;
   }
   if (piece && piece.color === game.turn()) {
     selected = square;
     render(game.moves({ square, verbose: true }));
   }
 }

 function play(from, to) {
   const p = current();
   const before = game.fen();
   const made = game.move({ from, to, promotion: 'q' });
   if (!made) {
     selected = null;
     render();
     return;
   }

   attempts++;
   $('puzzle-attempts').textContent = String(attempts);
   const isAnswer = from === p.solution.from && to === p.solution.to && made.san === p.solution.san;
   if (isAnswer) {
     solved = true;
     correct = 1;
     moveNo++;
     $('move-counter').textContent = 'Move ' + moveNo;
     ChessProgress.recordPuzzle(true);
     $('puzzle-feedback').className = 'puzzle-feedback good';
     $('puzzle-feedback').textContent = 'Correct! ' + p.why;
     $('puzzle-accuracy').textContent = Math.round(correct / attempts * 100) + '%';
     $('puzzle-completed').textContent = ChessProgress.get().puzzlesSolved;
     $('turn-indicator').textContent = 'Puzzle solved';
   } else {
     game.load(before);
     ChessProgress.recordPuzzle(false);
     $('puzzle-feedback').className = 'puzzle-feedback bad';
     $('puzzle-feedback').textContent = 'Not quite. That move is legal, but it is not the puzzle solution. Try again or use a hint.';
     $('puzzle-accuracy').textContent = Math.round(correct / attempts * 100) + '%';
   }
   selected = null;
   render();
 }

 $('puzzle-hint').addEventListener('click', () => {
   const p = current();
   if (!p || solved) return;
   hintStep = Math.min(hintStep + 1, p.hint.length);
   $('hint-box').hidden = false;
   $('hint-box').textContent = 'Hint ' + hintStep + ': ' + p.hint[hintStep - 1];
 });
 $('puzzle-reset').addEventListener('click', () => { if (current()) load(); });
 $('puzzle-next').addEventListener('click', () => {
   const available = filtered();
   if (!available.length) return;
   const currentPosition = available.findIndex(p => p.index === index);
   index = available[(currentPosition + 1) % available.length].index;
   load();
 });
 ['puzzle-difficulty', 'puzzle-theme'].forEach(id => $(id).addEventListener('change', () => {
   index = 0;
   load();
 }));

 if (!puzzles.length) {
   $('puzzle-title').textContent = 'Puzzles unavailable';
   $('puzzle-feedback').textContent = 'The puzzle positions could not be validated. Check that the chess rules library loaded correctly.';
 } else {
   load();
 }
})();
